                    "sql": "create or replace table snitch_db.maplemonk.POD_latest_complete_week as with params as ( select current_date() as run_date, date_trunc(\'month\', current_date()) as start_date, dateadd(day, -1, current_date()) as end_date, dateadd(day, 1, date_trunc(\'month\', current_date())) as opening_snapshot_date, (8 - dayofweekiso(date_trunc(\'month\', current_date()))) as first_week_end_day, case when day(current_date()) <= (8 - dayofweekiso(date_trunc(\'month\', current_date()))) then 1 else 2 + floor( ( day(current_date()) - (8 - dayofweekiso(date_trunc(\'month\', current_date()))) - 1 ) / 7 ) end as current_week_no, case when day(current_date()) <= (8 - dayofweekiso(date_trunc(\'month\', current_date()))) then 0 else ( 2 + floor( ( day(current_date()) - (8 - dayofweekiso(date_trunc(\'month\', current_date()))) - 1 ) / 7 ) ) - 1 end as latest_complete_week_no ), meta_map as ( select lower( iff( lower(replace(a.sku_group, \' \', \'\')) like \'mp%\' or lower(replace(a.sku_group, \' \', \'\')) like \'4c-%\', split_part(replace(a.sku_group, \' \', \'\'), \'-\', 1) || iff( split_part(replace(a.sku_group, \' \', \'\'), \'-\', 2) <> \'\', \'-\' || split_part(replace(a.sku_group, \' \', \'\'), \'-\', 2), \'\' ), split_part(replace(a.sku_group, \' \', \'\'), \'-\', 1) ) ) as sku_group_clean, lower( coalesce( min(case when lower(trim(a.l1_category)) = \'long tail\' then a.l1_category end), min(case when lower(trim(a.l1_category)) = \'plus\' then a.l1_category end), min(case when lower(trim(a.l1_category)) = \'luxe\' then a.l1_category end), min(case when lower(trim(a.l1_category)) = \'snitch\' then a.l1_category end), min(a.l1_category) ) ) as l1_category, lower( coalesce( min(case when lower(trim(a.category)) = \'shirts\' then a.category end), min(case when lower(trim(a.category)) = \'tshirts\' then a.category end), min(case when lower(trim(a.category)) = \'jeans\' then a.category end), min(case when lower(trim(a.category)) = \'trousers\' then a.category end), min(a.category) ) ) as category from snitch_db.maplemonk.meta_mapping_cogs_sku a group by 1 ), opening_inventory as ( select mm.l1_category, mm.category, sum( coalesce(cds.qty_available, 0) + coalesce(cds.qty_offline_available, 0) + coalesce(cds.qty_jit, 0) ) as opening_inventory_qty from snitch_db.maplemonk.cogs_daily_snapshot cds left join meta_map mm on mm.sku_group_clean = lower( iff( lower(replace(cds.sku_group, \' \', \'\')) like \'mp%\' or lower(replace(cds.sku_group, \' \', \'\')) like \'4c-%\', split_part(replace(cds.sku_group, \' \', \'\'), \'-\', 1) || iff( split_part(replace(cds.sku_group, \' \', \'\'), \'-\', 2) <> \'\', \'-\' || split_part(replace(cds.sku_group, \' \', \'\'), \'-\', 2), \'\' ), split_part(replace(cds.sku_group, \' \', \'\'), \'-\', 1) ) ) cross join params p where cds.date = p.opening_snapshot_date group by 1, 2 ), planned_base as ( select ib.sku as raw_sku, ib.final_sku as final_sku, ib.remarks_final as remarks_final, ib.qty as planned_qty, lower(replace(trim(ib.sku), \' \', \'\')) as raw_sku_clean, lower( iff( lower(replace(ib.final_sku, \' \', \'\')) like \'mp%\' or lower(replace(ib.final_sku, \' \', \'\')) like \'4c-%\', split_part(replace(ib.final_sku, \' \', \'\'), \'-\', 1) || iff( split_part(replace(ib.final_sku, \' \', \'\'), \'-\', 2) <> \'\', \'-\' || split_part(replace(ib.final_sku, \' \', \'\'), \'-\', 2), \'\' ), split_part(replace(ib.final_sku, \' \', \'\'), \'-\', 1) ) ) as final_sku_clean, case when lower(trim(ib.remarks_final)) = \'january skus\' then 1 when lower(trim(ib.remarks_final)) = \'february skus\' then 2 when lower(trim(ib.remarks_final)) = \'march skus\' then 3 when lower(trim(ib.remarks_final)) = \'april skus\' then 4 when lower(trim(ib.remarks_final)) = \'may skus\' then 5 when lower(trim(ib.remarks_final)) = \'june skus\' then 6 when lower(trim(ib.remarks_final)) = \'july skus\' then 7 when lower(trim(ib.remarks_final)) = \'august skus\' then 8 when lower(trim(ib.remarks_final)) = \'september skus\' then 9 when lower(trim(ib.remarks_final)) = \'october skus\' then 10 when lower(trim(ib.remarks_final)) = \'november skus\' then 11 when lower(trim(ib.remarks_final)) = \'december skus\' then 12 end as planned_month_no from snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks ib ), planned_current_month as ( select pb.*, mm.l1_category, mm.category from planned_base pb left join meta_map mm on mm.sku_group_clean = pb.final_sku_clean cross join params p where pb.planned_month_no = month(p.start_date) ), planned_for_weekly as ( select raw_sku_clean, final_sku_clean, lower(trim(remarks_final)) as remarks_final_clean, min(l1_category) as l1_category, min(category) as category, sum(planned_qty) as planned_qty from planned_current_month group by 1, 2, 3 ), planned_for_inward_match as ( select final_sku_clean, min(l1_category) as l1_category, min(category) as category, min(planned_month_no) as planned_month_no, sum(planned_qty) as planned_qty from planned_current_month group by 1 ), weekly_plan_raw as ( select lower(replace(trim(sku), \' \', \'\')) as raw_sku_clean, lower(trim(week)) as week_label, lower(trim(months)) as months_label from snitch_db.maplemonk.weekly_plan_inwards_weekly_plan ), weekly_plan_collapsed as ( select raw_sku_clean, months_label, min( case when week_label = \'week1\' then 1 when week_label = \'week2\' then 2 when week_label = \'week3\' then 3 when week_label = \'week4\' then 4 when week_label = \'week5\' then 5 end ) as min_week_no, max( case when week_label = \'week1\' then 1 when week_label = \'week2\' then 2 when week_label = \'week3\' then 3 when week_label = \'week4\' then 4 when week_label = \'week5\' then 5 end ) as max_week_no, count_if(week_label in (\'week1\',\'week2\',\'week3\',\'week4\',\'week5\')) as valid_week_rows from weekly_plan_raw where week_label in (\'week1\',\'week2\',\'week3\',\'week4\',\'week5\') group by 1, 2 ), actual_inwards_by_date as ( select lower( trim( reverse( substring( reverse(\"Item Type skuCode\"), charindex(\'-\', reverse(\"Item Type skuCode\")) + 1, len(\"Item Type skuCode\") ) ) ) ) as sku_group_from_putaway, cast(\"PUTAWAY_UPDATED\" as date) as inward_date, sum(\"PUTAWAY_COMPLETED_QUANTITY\") as inward_qty from snitch_db.maplemonk.putaway_tracking cross join params p where cast(\"PUTAWAY_UPDATED\" as date) >= p.start_date and cast(\"PUTAWAY_UPDATED\" as date) <= p.end_date and lower(final_type) like \'new%\' group by 1, 2 ) , actual_inwards_by_sku as ( select lower( iff( lower(replace(sku_group_from_putaway, \' \', \'\')) like \'mp%\' or lower(replace(sku_group_from_putaway, \' \', \'\')) like \'4c-%\', split_part(replace(sku_group_from_putaway, \' \', \'\'), \'-\', 1) || iff( split_part(replace(sku_group_from_putaway, \' \', \'\'), \'-\', 2) <> \'\', \'-\' || split_part(replace(sku_group_from_putaway, \' \', \'\'), \'-\', 2), \'\' ), split_part(replace(sku_group_from_putaway, \' \', \'\'), \'-\', 1) ) ) as inward_sku_clean, sum(inward_qty) as inward_qty_till_yesterday from actual_inwards_by_date group by 1 ), planned_same_month_inward as ( select pfim.final_sku_clean, sum(ai.inward_qty) as inwarded_in_same_month_qty from planned_for_inward_match pfim left join actual_inwards_by_date ai on lower( iff( lower(replace(ai.sku_group_from_putaway, \' \', \'\')) like \'mp%\' or lower(replace(ai.sku_group_from_putaway, \' \', \'\')) like \'4c-%\', split_part(replace(ai.sku_group_from_putaway, \' \', \'\'), \'-\', 1) || iff( split_part(replace(ai.sku_group_from_putaway, \' \', \'\'), \'-\', 2) <> \'\', \'-\' || split_part(replace(ai.sku_group_from_putaway, \' \', \'\'), \'-\', 2), \'\' ), split_part(replace(ai.sku_group_from_putaway, \' \', \'\'), \'-\', 1) ) ) = pfim.final_sku_clean and month(ai.inward_date) = pfim.planned_month_no group by 1 ), weekly_assignment as ( select pfw.raw_sku_clean, pfw.final_sku_clean, pfw.remarks_final_clean, pfw.l1_category, pfw.category, pfw.planned_qty, case when coalesce(wpc.valid_week_rows, 0) > 0 then case when coalesce(psmi.inwarded_in_same_month_qty, 0) > 0.5 * coalesce(pfw.planned_qty, 0) then wpc.min_week_no else wpc.max_week_no end when coalesce(psmi.inwarded_in_same_month_qty, 0) > 0 then 1 else p.current_week_no end as effective_week_no from planned_for_weekly pfw left join weekly_plan_collapsed wpc on pfw.raw_sku_clean = wpc.raw_sku_clean and pfw.remarks_final_clean = wpc.months_label left join planned_same_month_inward psmi on pfw.final_sku_clean = psmi.final_sku_clean cross join params p ), planned_upto_latest_complete_week as ( select l1_category, category, sum(planned_qty) as inwards_planned_upto_current_week_qty from weekly_assignment wa cross join params p where wa.effective_week_no <= p.latest_complete_week_no group by 1, 2 ), inwards_from_planned as ( select pfim.l1_category, pfim.category, sum(coalesce(absku.inward_qty_till_yesterday, 0)) as inwards_from_planned_qty from planned_for_inward_match pfim left join actual_inwards_by_sku absku on absku.inward_sku_clean = pfim.final_sku_clean group by 1, 2 ), total_inwards as ( select mm.l1_category, mm.category, sum(absku.inward_qty_till_yesterday) as total_inwards_qty from actual_inwards_by_sku absku left join meta_map mm on mm.sku_group_clean = absku.inward_sku_clean group by 1, 2 ), sales_target as ( select lower(trim(s.l_1_category)) as l1_category, lower(trim(s.category)) as category, sum(s.qty) * datediff(day, p.start_date, p.run_date) / day(last_day(p.start_date)) as sales_target_qty from snitch_db.maplemonk.sales_pred_channel_targets_set s cross join params p where to_date(s.month, \'dd/mm/yyyy\') = p.start_date group by 1, 2, p.start_date, p.run_date ) , actual_sales as ( select mm.l1_category, mm.category, sum(h.gross_quantity) as actual_sales_qty from snitch_db.maplemonk.horizontal_sales_categories h left join meta_map mm on mm.sku_group_clean = lower( iff( lower(replace(h.sku_group, \' \', \'\')) like \'mp%\' or lower(replace(h.sku_group, \' \', \'\')) like \'4c-%\', split_part(replace(h.sku_group, \' \', \'\'), \'-\', 1) || iff( split_part(replace(h.sku_group, \' \', \'\'), \'-\', 2) <> \'\', \'-\' || split_part(replace(h.sku_group, \' \', \'\'), \'-\', 2), \'\' ), split_part(replace(h.sku_group, \' \', \'\'), \'-\', 1) ) ) cross join params p where cast(h.date as date) >= p.start_date and cast(h.date as date) <= p.end_date group by 1, 2 ), returns_data as ( select mm.l1_category, mm.category, sum(pt.\"PUTAWAY_COMPLETED_QUANTITY\") as returns_qty from snitch_db.maplemonk.putaway_tracking pt left join meta_map mm on mm.sku_group_clean = lower( iff( lower( replace( trim( reverse( substring( reverse(pt.\"Item Type skuCode\"), charindex(\'-\', reverse(pt.\"Item Type skuCode\")) + 1, len(pt.\"Item Type skuCode\") ) ) ), \' \', \'\' ) ) like \'mp%\' or lower( replace( trim( reverse( substring( reverse(pt.\"Item Type skuCode\"), charindex(\'-\', reverse(pt.\"Item Type skuCode\")) + 1, len(pt.\"Item Type skuCode\") ) ) ), \' \', \'\' ) ) like \'4c-%\', split_part( replace( trim( reverse( substring( reverse(pt.\"Item Type skuCode\"), charindex(\'-\', reverse(pt.\"Item Type skuCode\")) + 1, len(pt.\"Item Type skuCode\") ) ) ), \' \', \'\' ), \'-\', 1 ) || iff( split_part( replace( trim( reverse( substring( reverse(pt.\"Item Type skuCode\"), charindex(\'-\', reverse(pt.\"Item Type skuCode\")) + 1, len(pt.\"Item Type skuCode\") ) ) ), \' \', \'\' ), \'-\', 2 ) <> \'\', \'-\' || split_part( replace( trim( reverse( substring( reverse(pt.\"Item Type skuCode\"), charindex(\'-\', reverse(pt.\"Item Type skuCode\")) + 1, len(pt.\"Item Type skuCode\") ) ) ), \' \', \'\' ), \'-\', 2 ), \'\' ), split_part( replace( trim( reverse( substring( reverse(pt.\"Item Type skuCode\"), charindex(\'-\', reverse(pt.\"Item Type skuCode\")) + 1, len(pt.\"Item Type skuCode\") ) ) ), \' \', \'\' ), \'-\', 1 ) ) ) cross join params p where cast(pt.\"PUTAWAY_UPDATED\" as date) >= p.start_date and cast(pt.\"PUTAWAY_UPDATED\" as date) <= p.end_date and lower(pt.final_type) like \'b2c return%\' group by 1, 2 ), all_cats as ( select l1_category, category from opening_inventory union select l1_category, category from planned_upto_latest_complete_week union select l1_category, category from inwards_from_planned union select l1_category, category from total_inwards union select l1_category, category from sales_target union select l1_category, category from actual_sales union select l1_category, category from returns_data ) select ac.l1_category, ac.category, coalesce(oi.opening_inventory_qty, 0) as opening_inventory_qty, coalesce(pucw.inwards_planned_upto_current_week_qty, 0) as inwards_planned_upto_current_week_qty, coalesce(ifp.inwards_from_planned_qty, 0) as inwards_from_planned_qty, coalesce(ti.total_inwards_qty, 0) as total_inwards_qty, coalesce(st.sales_target_qty, 0) as sales_target_qty, coalesce(asl.actual_sales_qty, 0) as actual_sales_qty, coalesce(rd.returns_qty, 0) as returns_qty from all_cats ac left join opening_inventory oi on ac.l1_category = oi.l1_category and ac.category = oi.category left join planned_upto_latest_complete_week pucw on ac.l1_category = pucw.l1_category and ac.category = pucw.category left join inwards_from_planned ifp on ac.l1_category = ifp.l1_category and ac.category = ifp.category left join total_inwards ti on ac.l1_category = ti.l1_category and ac.category = ti.category left join sales_target st on ac.l1_category = st.l1_category and ac.category = st.category left join actual_sales asl on ac.l1_category = asl.l1_category and ac.category = asl.category left join returns_data rd on ac.l1_category = rd.l1_category and ac.category = rd.category order by 1, 2;",
